/* ============================================================================
 * C0/8A6D  auto_walk_dispatch()  (DP=$1D00, entered with X/Y 8-bit)
 * Called from C0/881E (body) at 8847 only when $0120 != 0.
 *   8A6D LDA $30 ; 8A6F BEQ 8A82 ; 8A71 BMI 8A8F
 * Reads the velocity ACCUMULATOR $2E (X), $30 (Y) -- both signed 16-bit words
 * but only the low byte is loaded here (A is 8-bit: SEP #$20 not done, A-width
 * is whatever body left = 8-bit from 882A SEP #$20). BEQ/BMI test the 8-bit
 * low byte's value/sign. (See uncertainty: sign uses bit7 of $2E/$30 low byte.)
 * ==========================================================================*/
void auto_walk_dispatch(void) {           // 8A6D
    int8 vy = $30;                        // 8A6D LDA $30 (8-bit)
    if (vy == 0) {                        // 8A6F BEQ 8A82
        int8 vx = $2E;                    // 8A82 LDA $2E
        if (vx == 0) return;              // 8A84 BEQ 8A8E -> 8A8E RTS  (THE free-roam path)
        if (vx < 0)  goto h_8BC4_left();  // 8A86 BMI 8A8B ; 8A8B BRL 8BC4  (X<0,Y=0: WEST)
        else         goto h_8AB5_right(); // 8A88 BRL 8AB5            (X>0,Y=0: EAST)
    }
    if (vy < 0) {                         // 8A71 BMI 8A8F   (Y<0: NORTH group)
        int8 vx = $2E;                    // 8A8F LDA $2E
        if (vx == 0) goto h_8BF9_up();    // 8A9B BRL 8BF9            (X=0,Y<0: NORTH)
        if (vx < 0)  goto h_8EF1_upleft();// 8A98 BRL 8EF1            (X<0,Y<0: NW)
        else         goto h_8E21_upright();//8A95 BRL 8E21            (X>0,Y<0: NE)
    } else {                              // (Y>0: SOUTH group, 8A73)
        int8 vx = $2E;                    // 8A73 LDA $2E
        if (vx == 0) goto h_8D11_down();  // 8A7F BRL 8D11            (X=0,Y>0: SOUTH)
        if (vx < 0)  goto h_8FC1_dnleft();// 8A7C BRL 8FC1            (X<0,Y>0: SW)
        else         goto h_909C_dnright();//8A79 BRL 909C            (X>0,Y>0: SE)
    }
}

/* ----------------------------------------------------------------------------
 * C0/8A9E  probe_tile_solid()  -> returns A: 1 = solid/off-map, 0 = passable
 *   ($66 = tentative X word, $67 = its high byte, $68 = tentative Y word.)
 *   Always called with A 16-bit (REP #$20). Wraps the prop-fetch + z-gate.
 * --------------------------------------------------------------------------*/
uint8 probe_tile_solid(void) {            // 8A9E
    A16 = $68;                            // 8A9E LDA $68  (tentative Y, 16-bit)
    SEP_A8();                             // 8AA0
    A8 = $67;                             // 8AA2 LDA $67  (tentative X high byte)
    // 9AA1: REP#$20; A &= $1E (cell mask) -> X; if $7E70C0[X] bit7 -> off-map: SEC
    if (prop_fetch_off_map(&A))           // 8AA4 JSR 9AA1 ; 8AA7 BCC 8AAC
        return 1;                         // 8AA9 LDA #$01 ; 8AAB RTS  (solid: off the map)
    prop_fetch_full();                    // 8AAC JSR 9AD3  (decode shape + z, sets $6A/$6C/...)
    zgate();                              // 8AAF JSR 9C37  (z-plane gate, sets carry; ignored here)
    return 0;                             // 8AB2 LDA #$00 ; 8AB4 RTS  (passable-by-this-cheap-test)
}
/* NOTE: 8A9E's carry on return is from 9C37 (z-gate). The handlers branch on
 * BOTH the returned A (BNE/BEQ at e.g. 8B02) AND on carry (BCS/BCC). The A==1
 * path leaves carry SET (from 9AA1). The A==0 path leaves carry = z-gate result.
 * This dual signal is how the handlers distinguish "off-map" vs "z-solid". */

/* ----------------------------------------------------------------------------
 * C0/9923  probe_actor_block()  -> carry SET = blocked by another actor
 *   Walks active actor list ($7F2000=count*?, $0F00,X present, $1100,X flag);
 *   skips self ($0197) and $0199/$019B; for each candidate with $1B01,X bit0
 *   compares |$1880,X - $68| < $E0 AND |$1800,X - $66| < $E0 -> collide.
 *   bit0 set branch (9960..) returns SEC(9989) on hit; bit0 clear (99A1..)
 *   returns CLC(99CA) on hit. Off-screen actors ($0F00,X==0) skipped.
 * --------------------------------------------------------------------------*/
bool probe_actor_block(void);             // 9923 (sets $01EB scratch; restores X 16-bit)

/* ----------------------------------------------------------------------------
 * Each directional handler has the SAME skeleton. Example: EAST (h_8AB5).
 *   1. set the OTHER axis sub-pixel byte: STZ $2F/$31 or LDA #$FF;STA (sign-extend)
 *   2. X=$0197 (player actor); read on-map base pos $1800,X->$62, $1880,X->$64
 *   3. build a tentative probe point in $66/$68 (base +/- $70 feelers + vel $2E/$30)
 *   4. JSR 9923 (actor block test); if blocked -> STZ velocity, RTS
 *   5. cascade of JSR 8A9E feeler tests at +$70 / -$70 / center offsets;
 *      on the all-clear leaf: BRL/JSR 9C5C (commit the move, per-axis apply)
 *      on any blocked feeler: STZ $2E and/or $30, RTS  (cancel that axis)
 *   The $70 ($0070=112) is the half-tile feeler radius; $40 ($0040=64) the
 *   vertical foot offset. Diagonal handlers (8E21/8EF1/8FC1/909C) probe a
 *   corner box (X+/-$70 AND Y+/-$70) and fall back to the cardinal handler
 *   (e.g. 909C SE retries 8D11 down then 8BC4 west) when a corner is blocked.
 * --------------------------------------------------------------------------*/
void h_8AB5_right(void){                   // EAST  (X>0,Y=0)
    $2F=0; $31=0;                          // 8AB5/8AB7
    X=$0197;
    $62 = $1800,X;                         // base X
    $66 = $62 + 0x0070 + $2E;              // 8AC4/8AC7 tentative X (lead edge + vel)
    $64 = $1880,X;
    $68 = $64 - 0x0040;                    // 8AD1 foot Y (upper feeler)
    if (probe_actor_block()) { $2E=0; return; }   // 8AD8/8ADB
    $68 = $64;                             // 8AE6 mid feeler
    if (probe_8A9E_carry_set())            // 8AEA JSR 8A9E ; 8AED BCS 8B02
        ... handle off-map/z cases (8B02 cluster: probe lower foot $64-$70, set
            $30=-$10/+$10 to slide along, retry; on clear BRL 9C5C; else STZ vel,RTS)
    else { $68=$64-0x0070;                 // 8AF1 upper foot
           if (probe_8A9E_carry_set()) goto slide_8B4D;  // 8AFC
           else apply_9C5C(); return; }    // 8AFE JSR 9C5C ; 8B01 RTS  (CLEAR: commit)
    /* slide branches 8B1A/8B4D set $30 = -$10 or +$10 (vertical nudge to round a
       corner) and re-probe; commit via 9C5C or cancel via STZ $2E/$30. */
}
